#include "tanh_custom_tiling.h"
#include "register/op_def_registry.h"
#include "tiling/tiling_api.h"

namespace optiling {
const uint32_t BLOCK_DIM = 48;
const uint32_t ALIGN_NUM = 8;
const uint32_t MAX_TILE_LENGTH = 8192; // 每tile计算元素数
const uint32_t BUFFER_NUM = 2;
const uint32_t TYPE_SIZE = 4; // float32

static ge::graphStatus TilingFunc(gert::TilingContext *context)
{
    TanhCustomTilingData tiling;

    uint32_t totalLength = context->GetInputTensor(0)->GetShapeSize();
    // 计算每block长度并按对齐裁剪
    uint32_t blockLength = (totalLength / BLOCK_DIM);
    blockLength = (blockLength / ALIGN_NUM) * ALIGN_NUM;
    if (blockLength == 0 && totalLength > 0) {
        // 小规模场景至少给前(BLOCK_DIM-1)个block 0，最后一个block全量
        blockLength = 0;
    }
    uint32_t lastBlockLength = (totalLength > blockLength * (BLOCK_DIM - 1))
        ? (totalLength - blockLength * (BLOCK_DIM - 1)) : 0;

    // 设定tile长度
    uint32_t tileLength = MAX_TILE_LENGTH;

    // 计算临时缓冲区大小（按每tile计算规模估算）
    std::vector<int64_t> shape_vec = {static_cast<int64_t>(tileLength)};
    ge::Shape shape(shape_vec);
    uint32_t maxValue = 0;
    uint32_t minValue = 0;
    AscendC::GetTanhMaxMinTmpSize(shape, TYPE_SIZE, false, maxValue, minValue);

    // 结合UB容量与IO占用，估算可用tmp大小
    auto platformInfo = context->GetPlatformInfo();
    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo);
    uint64_t ubSize = 0;
    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    uint64_t ioReserve = static_cast<uint64_t>(tileLength) * TYPE_SIZE * BUFFER_NUM /*input*/ +
                         static_cast<uint64_t>(tileLength) * TYPE_SIZE * BUFFER_NUM /*output*/;
    uint32_t tmpSize = 0;
    if (ubSize > ioReserve) {
        uint64_t freeUB = ubSize - ioReserve;
        tmpSize = static_cast<uint32_t>(freeUB >= maxValue ? maxValue : freeUB);
        if (tmpSize < minValue) {
            // 若UB剩余不足以满足最小tmp，交由API框架内部分配
            tmpSize = 0;
        }
    } else {
        tmpSize = 0;
    }

    context->SetBlockDim(BLOCK_DIM);
    tiling.set_blockLength(blockLength);
    tiling.set_lastBlockLength(lastBlockLength);
    tiling.set_tileLength(tileLength);
    tiling.set_tmpBufferSize(tmpSize);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    context->SetTilingKey(1);
    return ge::GRAPH_SUCCESS;
}
} // namespace optiling

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext *context)
{
    const gert::Shape *x_shape = context->GetInputShape(0);
    gert::Shape *y_shape = context->GetOutputShape(0);
    *y_shape = *x_shape;
    return GRAPH_SUCCESS;
}
static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
    const ge::DataType x_dtype = context->GetInputDataType(0);
    context->SetOutputDataType(0, x_dtype);
    return GRAPH_SUCCESS;
}
} // namespace ge

